bounded_host_request.command:
set -eu
python3 - <<'PY'
import json
import os
import selectors
import subprocess
import sys
import time
p=subprocess.Popen(['docker','exec','-i','--workdir','/app','debug-ai-debug-ai-1','node','bin/debugai-mcp.mjs'],stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=subprocess.PIPE,bufsize=0)
sel=selectors.DefaultSelector()
sel.register(p.stdout,selectors.EVENT_READ)
records={}
buf=b''
def send(obj):
    p.stdin.write((json.dumps(obj,separators=(',',':'))+'\n').encode())
    p.stdin.flush()
def wait_for(id,limit=18):
    global buf
    deadline=time.monotonic()+limit
    while time.monotonic()<deadline:
        if id in records:return records[id]
        ready=sel.select(min(1,max(.01,deadline-time.monotonic())))
        if not ready:
            if p.poll() is not None:break
            continue
        raw=os.read(p.stdout.fileno(),65536)
        if not raw:break
        buf+=raw
        while b'\n' in buf:
            one,buf=buf.split(b'\n',1)
            try:obj=json.loads(one)
            except (ValueError,UnicodeError):continue
            if isinstance(obj,dict) and type(obj.get('id')) is int:records[obj['id']]=obj
    raise TimeoutError('MCP_RESPONSE_MISSING_'+str(id))
try:
    send({'jsonrpc':'2.0','id':1,'method':'initialize','params':{'protocolVersion':'2025-06-18','capabilities':{},'clientInfo':{'name':'gace-live-mcp-smoke','version':'1'}}})
    ini=wait_for(1).get('result',{})
    if not isinstance(ini,dict) or not ini.get('protocolVersion'):sys.exit(61)
    print('MCP_INIT=PASS')
    send({'jsonrpc':'2.0','method':'notifications/initialized','params':{}})
    send({'jsonrpc':'2.0','id':2,'method':'tools/list','params':{}})
    items=wait_for(2).get('result',{}).get('tools',[])
    names={i.get('name') for i in items if isinstance(i,dict)}
    print('MCP_TOOL_COUNT='+str(len(names)))
    if len(names)!=13 or 'debugai_health' not in names or any('approve' in n or 'apply' in n for n in names):sys.exit(62)
    print('MCP_TOOLS=PASS')
    send({'jsonrpc':'2.0','id':3,'method':'tools/call','params':{'name':'debugai_health','arguments':{}}})
    result=wait_for(3).get('result',{})
    blocks=result.get('content',[]) if isinstance(result,dict) else []
    payload={}
    for b in blocks:
        if isinstance(b,dict) and b.get('type')=='text':
            try:payload=json.loads(b.get('text',''))
            except ValueError:pass
            break
    print('MCP_HEALTH_SCHEMA='+str(payload.get('schema','MISSING'))[:60])
    print('MCP_HEALTH_ISERROR='+str(result.get('isError',False)))
    print('MCP_HEALTH_OK='+str(payload.get('result',{}).get('ok',None) if isinstance(payload.get('result'),dict) else None))
    if result.get('isError') is True or payload.get('schema')!='debugai.mcp-result/v1' or payload.get('result',{}).get('ok') is not True:sys.exit(63)
    print('MCP_LIVE_HEALTH=PASS')
except TimeoutError as e:
    print(str(e));sys.exit(64)
finally:
    if p.stdin and not p.stdin.closed:p.stdin.close()
    if p.poll() is None:p.terminate()
    try:p.wait(timeout=5)
    except subprocess.TimeoutExpired:p.kill()
PY
